use super::*;

pub(crate) fn event_from(evidence: &Evidence, flood: bool) -> Event {
    Event::RfDeauthFlood {
        flood,
        frames: evidence.frames,
        broadcast_frames: evidence.broadcast_frames,
        window_ms: evidence.window_ms,
        rate_centi_per_s: evidence.rate_centi_per_s,
        claimed_bssid: bounded_mac(&evidence.top_bssid),
        top_target: bounded_mac(&evidence.top_target),
        distinct_targets: evidence.distinct_targets,
        reasons: evidence.reasons.iter().copied().take(MAX_REASONS).collect(),
        // Carried through unbounded in count but bounded in shape: a channel is
        // a u16 and a signal an i8, so neither can inflate the datagram.
        freq_mhz: evidence.freq_mhz,
        top_transmitter: bounded_mac(&evidence.top_transmitter),
        strongest_dbm: evidence.strongest_dbm,
    }
}
